package vn.codegym.mvc;import vn.codegym.mvc.model.*;import vn.codegym.mvc.service.*;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import static org.junit.jupiter.api.Assertions.*;class MemoryServiceTest{
 @Test void productCrudAndCaseInsensitiveSearch(){var s=new ProductServiceImpl();var p=s.create(new Product("BÀN PHÍM",new BigDecimal("123.45"),"Mô tả","Hãng A"));assertTrue(s.search("bàn phím").stream().anyMatch(x->x.getId()==p.getId()));var updated=new Product("Chuột",BigDecimal.TEN,"Khác","Hãng B");updated.setId(p.getId());assertTrue(s.update(updated));assertEquals("Hãng B",s.findById(p.getId()).getManufacturer());assertTrue(s.delete(p.getId()));assertNull(s.findById(p.getId()));assertFalse(s.update(updated));}
 @Test void customerDetailAndMissingDelete(){var s=new CustomerServiceImpl();var c=s.create(new Customer("Người thử","test@example.com","Đà Nẵng"));assertEquals("Đà Nẵng",s.findById(c.getId()).getAddress());assertTrue(s.delete(c.getId()));assertFalse(s.delete(c.getId()));}
 @Test void identityIsNotReusedAfterDelete(){var s=new ProductServiceImpl();var a=s.create(new Product("A",BigDecimal.ONE,"A","A"));s.delete(a.getId());var b=s.create(new Product("B",BigDecimal.ONE,"B","B"));assertTrue(b.getId()>a.getId());}
}
